v = float(ARGS['value'])
f = ARGS['from'].strip().lower()
t = ARGS['to'].strip().lower()

length = {'mm': 0.001, 'cm': 0.01, 'm': 1.0, 'km': 1000.0, 'inch': 0.0254, 'ft': 0.3048, 'mi': 1609.344}
weight = {'mg': 1e-6, 'g': 0.001, 'kg': 1.0, 't': 1000.0, 'lb': 0.45359237, 'oz': 0.0283495}
data = {'b': 1.0, 'kb': 1024.0, 'mb': 1024.0 ** 2, 'gb': 1024.0 ** 3, 'tb': 1024.0 ** 4}

if f in length and t in length:
    print(v * length[f] / length[t])
elif f in weight and t in weight:
    print(v * weight[f] / weight[t])
elif f in data and t in data:
    print(v * data[f] / data[t])
elif f in ('c', 'f', 'k') and t in ('c', 'f', 'k'):
    c = v if f == 'c' else (v - 32) * 5 / 9 if f == 'f' else v - 273.15
    out = c if t == 'c' else c * 9 / 5 + 32 if t == 'f' else c + 273.15
    print(round(out, 6))
else:
    print('不支持的换算: %s -> %s' % (f, t))

import os, platform, shutil

cores = os.cpu_count()
print('CPU 核数: %s' % cores)
print('Python: %s' % platform.python_version())
try:
    du = shutil.disk_usage('/data')
    print('数据分区: 总 %.1f GB, 可用 %.1f GB' % (du.total / 2**30, du.free / 2**30))
except Exception as e:
    print('存储读取失败: %s' % e)
try:
    with open('/proc/meminfo') as f:
        for line in f:
            if line.startswith('MemTotal') or line.startswith('MemAvailable'):
                print(line.strip())
except Exception as e:
    print('内存读取失败: %s' % e)
